<span class="line"><span style="color:#ABB2BF;">                nums1[k--] </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> nums1[i--]; </span><span style="color:#7F848E;font-style:italic;">// 填入 nums1[i]，同时 i 和 k 前移</span></span>
